insert into public.story_bibles select * from jsonb_populate_recordset(null::public.story_bibles, '[{"id":"bib_the-moonlit-kingdom","series_id":"ser_the-moonlit-kingdom","world_name":"Aurelune","geography":"A kingdom of blue meadows and silver rivers beneath a moon that never fully sets. The silver court sits on a hill above Lake Vesper; the golden court of Seraphine''s family lies three days east across the Frozen River.","culture":"Courtiers speak softly after dusk out of respect for the moon. Paper lanterns carry wishes; snow is considered a blessing. Cartography of the sky is an honoured profession.","history":"The two courts have been polite rivals for two hundred years, since the Winter Accord divided the river between them. No one remembers exactly why the accord was signed.","atmosphere":"Silver light, cold air, warm interiors, slow candlelit corridors, distant bells.","rules":["The moon never fully sets over Aurelune.","Lanterns released on the lake drift towards whoever needs them most.","No one may raise their voice in the Moon Garden.","Magic is quiet and gentle – it never harms or frightens."],"themes":["Trust between former rivals","Finding home in unexpected places","Patience and quiet attention"],"established_facts":["Seraphine is the second daughter of the golden court.","Corin has mapped falling stars since he was seven.","One star is missing from Corin''s childhood map.","The old gardener, Maud, tends the Moon Garden and knew Seraphine''s grandmother.","The first snow fell in episode 7, during the shared supper on the Silver Bridge."],"unresolved_threads":["Where the missing star from Corin''s map went.","Why the Winter Accord was originally signed.","What Maud promised Seraphine''s grandmother."],"creator_preferences":["Keep conflict low; tension resolves within each episode.","End every episode somewhere warm and quiet.","Romance stays tender – lingering glances, shared silences, no explicit content."],"updated_at":"2026-08-15T17:06:57.588Z"},{"id":"bib_a-cabin-in-the-pines","series_id":"ser_a-cabin-in-the-pines","world_name":"Larch Hollow","geography":"A small mountain village of thirty houses, a bakery, a frozen pond, and an abandoned observatory on the ridge.","culture":"Everyone knows everyone; mysteries are solved over tea, never with accusations.","history":"Larch Hollow was a mining village until the silver ran out a century ago.","atmosphere":"Snow, woodsmoke, lamplight, ticking clocks, the hiss of a kettle.","rules":["No one is ever truly a villain.","Each mystery resolves gently by the end of the episode."],"themes":["Community","Second acts","Paying attention"],"established_facts":["Agnes Thorne is a retired librarian.","The cabin''s previous owner was a clockmaker named Tobias."],"unresolved_threads":["What the key under the mat opens."],"creator_preferences":["Cosy, low stakes, lots of tea."],"updated_at":"2026-09-02T17:06:57.588Z"},{"id":"bib_starlight-express","series_id":"ser_starlight-express","world_name":"Starlight Express","geography":"","culture":"","history":"","atmosphere":"","rules":[],"themes":[],"established_facts":[],"unresolved_threads":[],"creator_preferences":[],"updated_at":"2026-07-31T17:06:57.588Z"},{"id":"bib_the-secret-garden-nights","series_id":"ser_the-secret-garden-nights","world_name":"Secret Garden","geography":"","culture":"","history":"","atmosphere":"","rules":[],"themes":[],"established_facts":[],"unresolved_threads":[],"creator_preferences":[],"updated_at":"2026-06-16T17:06:57.588Z"},{"id":"bib_letters-from-lumen","series_id":"ser_letters-from-lumen","world_name":"Letters from Lumen","geography":"","culture":"","history":"","atmosphere":"","rules":[],"themes":[],"established_facts":[],"unresolved_threads":[],"creator_preferences":[],"updated_at":"2026-09-09T17:06:57.588Z"},{"id":"bib_the-floating-library","series_id":"ser_the-floating-library","world_name":"Floating Library","geography":"","culture":"","history":"","atmosphere":"","rules":[],"themes":[],"established_facts":[],"unresolved_threads":[],"creator_preferences":[],"updated_at":"2026-07-16T17:06:57.588Z"},{"id":"bib_the-lantern-keepers-daughter","series_id":"ser_the-lantern-keepers-daughter","world_name":"The Thornwood Border","geography":"A village of thatched cottages on the edge of the Thornwood, an ancient forest ruled by a gentle fae court.","culture":"Villagers leave honey cakes at the forest edge. The forest court values courtesy above all else.","history":"Lanterns have marked the border since a truce between village and forest three hundred years ago.","atmosphere":"Warm lantern-light against deep green dark; moss, fireflies, the smell of rain on bark.","rules":["Lanterns must be lit at dusk and extinguished at dawn.","No mortal may enter the Thornwood uninvited.","Fireflies keep their promises."],"themes":["Duty and longing","Boundaries that soften","Small acts of care"],"established_facts":["Wren has lit the lanterns since her mother retired.","Ash is a knight of the forest court, made partly of moss and silver.","The fireflies owe Wren''s family an old debt."],"unresolved_threads":["What the fireflies'' debt was for.","Whether Wren will ever be invited into the forest."],"creator_preferences":["Lots of nature description.","Dialogue between Wren and Ash should be gently teasing."],"updated_at":"2026-09-23T17:06:57.588Z"},{"id":"bib_the-tidewater-inn","series_id":"ser_the-tidewater-inn","world_name":"Tidewater Inn","geography":"","culture":"","history":"","atmosphere":"","rules":[],"themes":[],"established_facts":[],"unresolved_threads":[],"creator_preferences":[],"updated_at":"2026-08-25T17:06:57.588Z"},{"id":"bib_orbit-of-quiet","series_id":"ser_orbit-of-quiet","world_name":"Orbit of Quiet","geography":"","culture":"","history":"","atmosphere":"","rules":[],"themes":[],"established_facts":[],"unresolved_threads":[],"creator_preferences":[],"updated_at":"2026-07-06T17:06:57.588Z"},{"id":"bib_the-clockmakers-snow","series_id":"ser_the-clockmakers-snow",