insert into public.characters select * from jsonb_populate_recordset(null::public.characters, '[{"id":"chr_the-moonlit-kingdom_seraphine","series_id":"ser_the-moonlit-kingdom","name":"Seraphine","age_range":"Mid-twenties","personality":"Curious, thoughtful, a little guarded, quietly funny.","backstory":"Second daughter of the golden court, sent to the silver court as a gesture of goodwill.","motivations":"To prove she is more than a diplomatic gift; to find somewhere she belongs.","narrative_role":"Protagonist","voice_profile":"Soft, clear, measured; speaks in short sentences when moved.","arc":"From wary guest to someone who chooses to stay.","portrait":{"scene":"portrait","palette":["hsl(250 45% 18%)","hsl(290 40% 30%)","hsl(250 70% 78%)","hsl(270 80% 88%)"],"seed":2510988346},"created_at":"2026-08-15T17:06:57.588Z","updated_at":"2026-08-15T17:06:57.588Z"},{"id":"chr_the-moonlit-kingdom_corin","series_id":"ser_the-moonlit-kingdom","name":"Corin","age_range":"Late twenties","personality":"Gentle, absent-minded, patient, observant.","backstory":"The silver court''s royal cartographer, who prefers stars to state dinners.","motivations":"To complete his map of falling stars; to find the missing star.","narrative_role":"Love interest","voice_profile":"Low and unhurried, often pauses mid-thought.","arc":"From solitary mapmaker to someone who shares his tower – and his map.","portrait":{"scene":"portrait","palette":["hsl(297 45% 18%)","hsl(337 40% 30%)","hsl(297 70% 78%)","hsl(317 80% 88%)"],"seed":826519668},"created_at":"2026-08-15T17:06:57.588Z","updated_at":"2026-08-15T17:06:57.588Z"},{"id":"chr_the-moonlit-kingdom_maud","series_id":"ser_the-moonlit-kingdom","name":"Maud","age_range":"Seventies","personality":"Wry, warm, knowing.","backstory":"Keeper of the Moon Garden for fifty years; knew Seraphine''s grandmother.","motivations":"To keep an old promise.","narrative_role":"Mentor","voice_profile":"Gravelly and kind, fond of proverbs.","arc":"Gradually reveals what she knows about the Winter Accord.","portrait":{"scene":"portrait","palette":["hsl(344 45% 18%)","hsl(24 40% 30%)","hsl(344 70% 78%)","hsl(4 80% 88%)"],"seed":996629546},"created_at":"2026-08-15T17:06:57.588Z","updated_at":"2026-08-15T17:06:57.588Z"},{"id":"chr_a-cabin-in-the-pines_agnes-thorne","series_id":"ser_a-cabin-in-the-pines","name":"Agnes Thorne","age_range":"Late sixties","personality":"Sharp, kind, endlessly curious.","backstory":"Forty years as a city librarian before retiring to the mountains.","motivations":"To belong somewhere new.","narrative_role":"Protagonist / amateur sleuth","voice_profile":"Crisp, warm, amused.","arc":"From newcomer to the village''s trusted puzzle-solver.","portrait":{"scene":"portrait","palette":["hsl(30 45% 18%)","hsl(70 40% 30%)","hsl(30 70% 78%)","hsl(50 80% 88%)"],"seed":1851655759},"created_at":"2026-09-02T17:06:57.588Z","updated_at":"2026-09-02T17:06:57.588Z"},{"id":"chr_the-lantern-keepers-daughter_wren","series_id":"ser_the-lantern-keepers-daughter","name":"Wren","age_range":"Early twenties","personality":"Steady, dry humour, secretly romantic.","backstory":"The lantern keeper''s daughter, now keeper herself.","motivations":"To keep her family''s promise; to see what lies inside the forest.","narrative_role":"Protagonist","voice_profile":"Warm, wry, unhurried.","arc":"Learns that keeping a border can also mean building a bridge.","portrait":{"scene":"portrait","palette":["hsl(290 45% 18%)","hsl(330 40% 30%)","hsl(290 70% 78%)","hsl(310 80% 88%)"],"seed":4059929951},"created_at":"2026-09-23T17:06:57.588Z","updated_at":"2026-09-23T17:06:57.588Z"},{"id":"chr_the-lantern-keepers-daughter_ash","series_id":"ser_the-lantern-keepers-daughter","name":"Ash","age_range":"Ageless (appears late twenties)","personality":"Formal, earnest, unexpectedly shy.","backstory":"A knight of the forest court tasked with extinguishing the lanterns each dawn.","motivations":"Duty to the court; growing curiosity about the mortal world.","narrative_role":"Love interest","voice_profile":"Quiet and precise, archaic phrasing.","arc":"From rule-bound guardian to someone who bends the rules for kindness.","portrait":{"scene":"portrait","palette":["hsl(337 45% 18%)","hsl(17 40% 30%)","hsl(337 70% 78%)","hsl(357 80% 88%)"],"seed":2080202783},"created_at":"2026-09-23T17:06:57.588Z","updated_at":"2026-09-23T17:06:57.588Z"}]'::jsonb);
