insert into public.agent_configurations select * from jsonb_populate_recordset(null::public.agent_configurations, '[{"id":"agent_showrunner","agent":"showrunner","name":"Showrunner","description":"Develops series, plans seasons, proposes the next episode and keeps the creative direction coherent.","provider":"auto","model":"claude-opus-5-5","prompt_template":"You are the showrunner for a Calm Sleep Story series. Using the Story Bible, propose the next episode that advances one unresolved thread gently, with low stakes and a restful ending.","temperature":0.8,"max_cost_cents_per_job":60,"retry_limit":2,"enabled":true,"updated_at":"2026-03-28T17:06:57.588Z"},{"id":"agent_writer","agent":"writer","name":"Writer","description":"Writes full narration scripts and dialogue in the series'' established tone.","provider":"auto","model":"claude-opus-5-5","prompt_template":"Write a Sleep Story script for calm narration. Long, flowing sentences, rich sensory detail, slow pacing, no cliffhangers, a soft and settled ending.","temperature":0.85,"max_cost_cents_per_job":250,"retry_limit":2,"enabled":true,"updated_at":"2026-03-28T17:06:57.588Z"},{"id":"agent_continuity","agent":"continuity","name":"Continuity","description":"Checks scripts against established facts, world rules and character profiles; flags contradictions.","provider":"auto","model":"claude-opus-5-5","prompt_template":"Compare the script with the Story Bible. List contradictions with evidence. Never rewrite lore.","temperature":0.1,"max_cost_cents_per_job":40,"retry_limit":2,"enabled":true,"updated_at":"2026-03-28T17:06:57.588Z"},{"id":"agent_sleep_editor","agent":"sleep_editor","name":"Sleep Editor","description":"Reduces overstimulation, softens distressing content, slows pacing and ensures a relaxing ending.","provider":"auto","model":"claude-opus-5-5","prompt_template":"Review for sleep suitability: remove sudden tension, loud events and distressing content; slow the pacing; make sure the ending is restful.","temperature":0.3,"max_cost_cents_per_job":60,"retry_limit":2,"enabled":true,"updated_at":"2026-03-28T17:06:57.588Z"},{"id":"agent_voice_director","agent":"voice_director","name":"Voice Director","description":"Selects approved voices, keeps narration settings consistent and prepares pronunciation notes.","provider":"auto","model":"claude-opus-5-5","prompt_template":"Prepare TTS direction: pacing marks, pronunciation guide for invented names, consistent voice settings.","temperature":0.2,"max_cost_cents_per_job":20,"retry_limit":2,"enabled":true,"updated_at":"2026-03-28T17:06:57.588Z"},{"id":"agent_audio_producer","agent":"audio_producer","name":"Audio Producer","description":"Generates narration, selects soundscapes, mixes and masters audio, and runs audio QA.","provider":"auto","model":"eleven_multilingual_v2","prompt_template":"","temperature":0,"max_cost_cents_per_job":900,"retry_limit":3,"enabled":true,"updated_at":"2026-03-28T17:06:57.588Z"},{"id":"agent_publishing","agent":"publishing","name":"Publishing","description":"Prepares metadata and descriptions, proposes release slots and submits episodes for editorial approval.","provider":"auto","model":"claude-opus-5-5","prompt_template":"Write a two-sentence, spoiler-free episode description in the series'' voice.","temperature":0.6,"max_cost_cents_per_job":10,"retry_limit":2,"enabled":true,"updated_at":"2026-03-28T17:06:57.588Z"}]'::jsonb);
